        node = node.args[0]
    if isinstance(node, (ast.Set, ast.List, ast.Tuple)):
        vals = [e.value for e in node.elts if isinstance(e, ast.Constant) and isinstance(e.value, str)]
        if vals and len(vals) == len(node.elts):
            return frozenset(vals)
    return None

