    tree = ast.parse(open(R + 'scripts/' + mod, encoding='utf-8').read())
    for node in tree.body:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            tgt = node.targets[0] if isinstance(node, ast.Assign) else node.target
            name = getattr(tgt, 'id', None)
            val = strs(node.value) if node.value is not None else None
            if not name or not val or len(val) < 2:
                continue
            eq = [k for k, v in checks.items() if v == val]
            sub = [k for k, v in checks.items() if val < v]
            if eq or sub:
                print(mod, name, sorted(val)[:6], 'EQUALS' if eq else '', eq[:3], 'SUBSET-OF' if sub else '', sub[:3])

