man = [json.loads(l) for l in open(LOG + 'manifest.jsonl', encoding='utf-8') if l.strip()]
N = lambda s: rl.normalise_quote(urllib.parse.unquote_plus(s or ''))

def link_candidates(con):
    """artefact -> set of execs in the SAME session whose query_text names its host and
    carries its longest query value verbatim (normalised)."""
    execs = con.execute('select exec_id, query_text from search_executions where created_by_session=?',
                        (SESSION,)).fetchall()
    out = {}
    for m in man:
        if m.get('derived'):
            continue
        u = urllib.parse.urlsplit(m['url'])
        host = u.netloc.removeprefix('www.')
        vals = [v for _, v in urllib.parse.parse_qsl(u.query) if not v.isdigit()]
        if not vals:
            continue
        key = N(max(vals, key=len))
        hits = {e for e, q in execs if host in (q or '') and key and key in N(q)}
        if hits:
            out.setdefault(m['artefact'], set()).update(hits)
            out.setdefault(('label', m['artefact']), set()).add(m['purpose'][:3].strip())
    return out

DOI = re.compile(r'10\.\d{4,9}/[^\s,;\)]+')
def doi_of(loc):
    d = {x.rstrip('.') for x in DOI.findall(loc or '')}
    return d.pop() if len(d) == 1 else None

def body(a):
    text, _ = rl.decode_artefact(open(LOG + a, 'rb').read())
    return N(text or '')

